{
  "name": "Thorlabs PM100USB 光功率计",
  "name_en": "Thorlabs PM100USB Optical Power Meter",
  "manufacturer": "Thorlabs",
  "description": "一款通过 USB 连接并使用 SCPI 指令控制的光功率计，用于配合已连接的光学传感器读取当前测量配置下的光功率等测量值。该设备支持设置平均采样次数、查询传感器信息以及读取校准相关信息，适合实验室中的激光与光学功率测量。",
  "description_en": "A USB-connected, SCPI-controlled optical power meter used with a connected optical sensor to read optical power and related measurements under the current measurement configuration. It supports averaging setup, sensor information queries, and calibration-related information retrieval for laboratory laser and optical power measurements.",
  "actions": [
    {
      "action_name": "auto-averaging_count",
      "description": "获取/设置每次测量的平均采样次数。",
      "description_en": "Get/set the number of samples averaged for each measurement."
    },
    {
      "action_name": "auto-cache_units",
      "description": "获取/设置是否缓存测量单位。",
      "description_en": "Get/set whether measurement units are cached."
    },
    {
      "action_name": "auto-measurement_configuration",
      "description": "获取/设置测量配置模式。",
      "description_en": "Get/set the measurement configuration mode."
    },
    {
      "action_name": "auto-read",
      "description": "读取当前测量配置模式下的测量值。",
      "description_en": "Read a measurement according to the current measurement configuration mode."
    },
    {
      "action_name": "auto-sensor",
      "description": "获取当前连接传感器的信息。",
      "description_en": "Get information about the currently connected sensor."
    },
    {
      "action_name": "auto-name",
      "description": "获取当前连接传感器的名称。",
      "description_en": "Get the name of the currently connected sensor."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取当前连接传感器的序列号。",
      "description_en": "Get the serial number of the currently connected sensor."
    },
    {
      "action_name": "auto-calibration_message",
      "description": "获取当前连接传感器的校准信息。",
      "description_en": "Get the calibration information for the currently connected sensor."
    },
    {
      "action_name": "auto-type",
      "description": "获取当前连接传感器的类型。",
      "description_en": "Get the type of the currently connected sensor."
    },
    {
      "action_name": "auto-flags",
      "description": "获取当前连接传感器的状态标志信息。",
      "description_en": "Get status flag information for the currently connected sensor."
    }
  ],
  "tag_hints": [
    "optical power measurement",
    "laser power meter",
    "Thorlabs PM100USB",
    "USB SCPI instrument",
    "photodiode/thermal sensor readout",
    "averaging configuration",
    "sensor calibration info"
  ]
}

